--- current/src/routes/records.ts ---
export function listRecords(rows: Array<{ title: string }>) {
  return rows.map(row => ({ title: row.title }));
}

--- current/src/search/queryIndex.ts ---
export function filterRecords(rows: Array<{ title: string }>, query: string) {
  const needle = query.toLowerCase().trim();
  return rows.filter(row => row.title.toLowerCase().includes(needle));
}

